from pathlib import Path
import re

def patch_file(path, fn):
    p=Path(path); s=p.read_text(encoding='utf-8'); s=fn(s); p.write_text(s,encoding='utf-8')

def one(s,old,new,label):
    n=s.count(old)
    if n!=1: raise SystemExit(f'{label}: expected 1, found {n}')
    return s.replace(old,new,1)

def sub(s,pat,repl,label):
    s2,n=re.subn(pat,repl,s,count=1,flags=re.S)
    if n!=1: raise SystemExit(f'{label}: expected 1, found {n}')
    return s2

