    s=one(s,"    const list=data.filter(r=>{\n      const hay=norm([r.date,r.name,r.jobTitle,r.email,r.category,r.status,r.inDistanceM,r.outDistanceM,r.inDistanceM2,r.outDistanceM2,r.source,r.editedBy,r.reason,r.inIp,r.outIp,r.inIp2,r.outIp2,r.ipCheck].join(' '));\n      return(!q||hay.includes(q))&&(!cat||r.category===cat)&&(!st||String(r.status||'').includes(st))&&(!src||r.source===src);\n    });","    const list=sortRecords(data.filter(r=>{\n      const hay=norm([r.date,r.name,r.jobTitle,r.email,r.category,r.status,r.inDistanceM,r.outDistanceM,r.inDistanceM2,r.outDistanceM2,r.source,r.editedBy,r.reason,r.inIp,r.outIp,r.inIp2,r.outIp2,r.ipCheck].join(' '));\n      return(!q||hay.includes(q))&&(!cat||r.category===cat)&&(!st||String(r.status||'').includes(st))&&(!src||r.source===src);\n    }),document.getElementById('reportSort')?.value||'name_asc');",'report sort')
    s=one(s,"    const list=data.filter(u=>{\n      const ps=userPinState(u),hay=norm([u.active?'aktif':'tidak aktif',u.name,u.jobTitle,u.email,u.category,u.isAdmin?'pentadbir sistem':'bukan admin',ps,u.s1In,u.s1Out,u.s2In,u.s2Out,u.note,u.lockedUntil,u.hasProfilePhoto?'gambar profil':'tiada gambar'].join(' '));\n      return(!q||hay.includes(q))&&(!cat||u.category===cat)&&(!active||(active==='active'?u.active:!u.active))&&(!adm||(adm==='yes'?u.isAdmin:!u.isAdmin))&&(!pw||ps===pw);\n    });","    const list=sortRecords(data.filter(u=>{\n      const ps=userPinState(u),hay=norm([u.active?'aktif':'tidak aktif',u.name,u.jobTitle,u.email,u.category,u.isAdmin?'pentadbir sistem':'bukan admin',ps,u.s1In,u.s1Out,u.s2In,u.s2Out,u.note,u.lockedUntil,u.hasProfilePhoto?'gambar profil':'tiada gambar'].join(' '));\n      return(!q||hay.includes(q))&&(!cat||u.category===cat)&&(!active||(active==='active'?u.active:!u.active))&&(!adm||(adm==='yes'?u.isAdmin:!u.isAdmin))&&(!pw||ps===pw);\n    }),document.getElementById('userSort')?.value||'name_asc');",'user sort')
    s=one(s,"async function submitTimeReview(ev,id,decision){ev.preventDefault();const comment=new FormData(ev.target).get('comment')||'';try{const r=await runServer('reviewTimeException',state.token,id,decision,comment);closeModal();toast(`${r.status} oleh ${r.reviewerName}.`,4500);state.timeReview=null;state.myCardLoaded=false;state.adminCardData=null;await loadTimeReview(true);}catch(e){handleServerError(e);}}","async function submitTimeReview(ev,id,decision){ev.preventDefault();const comment=new FormData(ev.target).get('comment')||'';try{const r=await runServer('reviewTimeException',state.token,id,decision,comment);closeModal();toast(`${r.status}.`,4500);state.timeReview=null;state.myCardLoaded=false;state.adminCardData=null;await loadTimeReview(true);}catch(e){handleServerError(e);}}",'toast')
